sp_VerificarSaldoEstoque	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_VerificarSaldoEstoque`(\n\n    IN p_idEmpresa INT,\n\n    IN p_ids       VARCHAR(1000)\n\n)\nBEGIN\n\n    SELECT\n\n        p.idProduto,\n\n        p.Nome                     AS nomeProduto,\n\n        COALESCE(e.Quantidade, 0)  AS qtdDisponivel\n\n    FROM Produto p\n\n    LEFT JOIN Estoque e\n\n        ON  e.IdProduto = p.idProduto\n\n        AND e.IdEmpresa = p_idEmpresa\n\n    WHERE FIND_IN_SET(p.idProduto, p_ids) > 0;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
